result = {}
places = []

def name_of(x):
    if isinstance(x, str):
        return x
    if isinstance(x, dict):
        for k in ("name", "english_name", "english", "name_english", "label", "common"):
            v = x.get(k)
            if isinstance(v, str) and v:
                return v
            if isinstance(v, dict):
                for kk in ("english", "common", "en"):
                    if isinstance(v.get(kk), str) and v.get(kk):
                        return v.get(kk)
        names = x.get("names")
        if isinstance(names, dict):
            for kk in ("english", "common", "en"):
                if isinstance(names.get(kk), str) and names.get(kk):
                    return names.get(kk)
    return None

def rate_num(v):
    s = str(v or "0").lower().replace("h", "")
    try:
        return int(s)
    except ValueError:
        return 0

for item in _items:
    data = item.get("json", {})
    if not isinstance(data, dict):
        continue

    inner = data.get("data")
    if "xid" in data:
        # OpenTripMap place (one item per place)
        nm = str(data.get("name") or "").strip()
        if nm:
            kinds = str(data.get("kinds") or "").split(",")[:2]
            dist = data.get("dist")
            places.append({
                "name": nm,
                "type": ", ".join(k.replace("_", " ") for k in kinds if k),
                "rate": rate_num(data.get("rate")),
                "dist_m": round(dist) if isinstance(dist, (int, float)) else None,
            })

    elif isinstance(inner, dict) and isinstance(inner.get("objects"), list):
        objs = inner["objects"]
        c = objs[0] if objs else {}
        result["country"] = (c.get("names") or {}).get("common")
        result["currency_code"] = data.get("currency_code")
        caps = c.get("capitals") or []
        result["capital"] = name_of(caps[0]) if caps else None

        langs = c.get("languages") or []
        if isinstance(langs, dict):
            langs = list(langs.values())
        result["languages"] = [n for n in (name_of(l) for l in langs) if n]

        curs = c.get("currencies") or {}
        out = []
        if isinstance(curs, dict):
            for code, v in curs.items():
                out.append(name_of(v) or str(code))
        elif isinstance(curs, list):
            for v in curs:
                n = name_of(v)
                if n:
                    out.append(n)
        result["currencies"] = out

    elif "daily" in data:
        cur = data.get("current") or {}
        d = data.get("daily") or {}
        result["temp_now_c"] = cur.get("temperature_2m")
        result["feels_like_c"] = cur.get("apparent_temperature")
        days = d.get("time") or []
        mins = d.get("temperature_2m_min") or []
        maxs = d.get("temperature_2m_max") or []
        rain = d.get("precipitation_probability_max") or []
        forecast = []
        for i in range(len(days)):
            forecast.append({
                "date": days[i],
                "min_c": mins[i] if i < len(mins) else None,
                "max_c": maxs[i] if i < len(maxs) else None,
                "rain_pct": rain[i] if i < len(rain) else None,
            })
        result["daily_forecast"] = forecast

    elif "european_aqi" in (data.get("current") or {}):
        result["european_aqi"] = data["current"].get("european_aqi")
        result["pm2_5"] = data["current"].get("pm2_5")

    elif "rates" in data:
        result["forex_base"] = data.get("base")
        result["forex_rates"] = data.get("rates")

if places:
    places.sort(key=lambda p: (-p["rate"], p["dist_m"] if p["dist_m"] is not None else 10**9))
    seen = []
    top = []
    for p in places:
        key = p["name"].strip().lower()
        if key in seen:
            continue
        seen.append(key)
        top.append({"name": p["name"], "type": p["type"], "dist_m": p["dist_m"]})
        if len(top) >= 12:
            break
    result["attractions"] = top

return [{"json": {"nomad_data": result}}]
